  function primarySentimentBreakdown(counts={}){
    const items=primarySentimentOrder.map((key)=>[key,primarySentimentLabels[key],Number(counts[key]||0)]);
    const total=items.reduce((sum,[,,count])=>sum+count,0);
    if(total===0)return {total,items:items.map(([key,label,count])=>({key,label,count,tenths:0}))};
    const allocated=items.map(([key,label,count],index)=>({key,label,count,index,tenths:Math.floor(count*1000/total),remainder:(count*1000)%total}));
    let remaining=1000-allocated.reduce((sum,item)=>sum+item.tenths,0);
    const remainderOrder=[...allocated].sort((a,b)=>b.remainder-a.remainder||a.index-b.index);
    for(let index=0;index<remaining;index+=1)remainderOrder[index%remainderOrder.length].tenths+=1;
    return {total,items:allocated};
  }
