    const types=(contract.legacy_type_order||[]).filter((id)=>allPosts.some((post)=>(post.legacy_event_types||[]).includes(id)));
    const filtered=allPosts.filter((post)=>(!state.automaticType||(post.legacy_event_types||[]).includes(state.automaticType))&&(!state.automaticMonth||post.month===state.automaticMonth));
    const shown=filtered.slice(0,state.automaticVisible);
